"// Analyze slot coverage and benchmark strategy ideas
const SLOTS = [
  [3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],
  [14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]
].map(([tx, ty], i) => ({ slot: i, tx, ty, x: tx * 100 + 50, y: ty * 100 + 50 }));

const GROUND_PTS = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]].map(([tx, ty]) => [tx * 100 + 50, ty * 100 + 50]);
const AIR_PTS = [[0,6],[21,6],[21,11],[23,11]].map(([tx, ty]) => [tx * 100 + 50, ty * 100 + 50]);

function sampleRoute(pts, step = 10) {
  const out = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const [x0, y0] = pts[i], [x1, y1] = pts[i + 1];
    const len = Math.abs(x1 - x0) + Math.abs(y1 - y0);
    const sx = Math.sign(x1 - x0), sy = Math.sign(y1 - y0);
    for (let d = 0; d < len; d += step) {
      out.push([x0 + sx * d, y0 + sy * d]);
    }
  }
  out.push(pts[pts.length - 1]);
  return out;
}

const gSamples = sampleRoute(GROUND_PTS, 10);
const aSamples = sampleRoute(AIR_PTS, 10);

const coverage = SLOTS.map(sl => {
  const g240 = gSamples.filter(([x,y]) => (x-sl.x)**2 + (y-sl.y)**2 <= 240**2).length * 10;
  const g260 = gSamples.filter(([x,y]) => (x-sl.x)**2 + (y-sl.y)**2 <= 260**2).length * 10;
  const g300 = gSamples.filter(([x,y]) => (x-sl.x)**2 + (y-sl.y)**2 <= 300**2).length * 10;
  const g360 = gSamples.filter(([x,y]) => (x-sl.x)**2 + (y-sl.y)**2 <= 360**2).length * 10;
  const g420 = gSamples.filter(([x,y]) => (x-sl.x)**2 + (y-sl.y)**2 <= 420**2).length * 10;
  const a300 = aSamples.filter(([x,y]) => (x-sl.x)**2 + (y-sl.y)**2 <= 300**2).length * 10;
  const a320 = aSamples.filter(([x,y]) => (x-sl.x)**2 + (y-sl.y)**2 <= 320**2).length * 10;
  const a380 = aSamples.filter(([x,y]) => (x-sl.x)**2 + (y-sl.y)**2 <= 380**2).length * 10;
  return { slot: sl.slot, tx: sl.tx, ty: sl.ty, g240, g260, g300, g360, g420, a300, a320, a380 };
});

JSON.stringify(coverage, null, 2);
